43	    /**
44	     * Opens a file using the default app.
45	     *
46	     * @param f the file
47	     */
48	    @Override
49	    protected void openFile(FMFile f) {
50	        if (new Pref<Boolean>(ZIPS_EXPLORABLE).getValue() && f.isArchive() && !(f instanceof FMArchive)) {
51	            activity.loadPath(f.getAbsolutePath());
52	        } else {
53	            Intent i = new Intent(Intent.ACTION_VIEW);
54	            i.setDataAndType(Uri.fromFile(f.getFile()), FMFile.getMimeTypeFromFile(f));
55	            i.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
56	            try {
57	                getContext().startActivity(i);
58	            } catch (ActivityNotFoundException e) {
59	                Toast.makeText(getContext(), R.string.no_app_to_handle_file, LENGTH_SHORT).show();
60	            }
61	        }
62	    }
63	
64	    /**
65	     * Gets the size of a file as formatted string.
66	     *
67	     * @param f the file
68	     * @return the size, formatted.
69	     */
70	    private String getSizeFormatted(FMFile f) {
71	        String[] units = new String[]{"B", "KiB", "MiB", "GiB", "TiB", "PiB"};
72	        Long length = f.getFile().length();
73	        if (Objects.equals(length, 0L)) {
74	            return "0";
75	        }
76	        Double number = Math.floor(Math.log(length) / Math.log(1024));
77	        Double pow = Math.pow(1024, Math.floor(number));
78	        Double d = length / pow;
79	        String formattedString = d.toString().substring(0, d.toString().indexOf(".") + 2);
80	        return formattedString + ' ' + units[number.intValue()];
81	    }
