83	    /**
84	     * Initializes the UI for each file.
85	     *
86	     * @param f the file
87	     * @return the initialized UI
88	     */
89	    @Override
90	    protected View initUI(FMFile f) {
91	        assert activity != null;
92	
93	        @SuppressLint("InflateParams") View v = LayoutInflater.from(activity).inflate(R.layout.layout_file, null); // works.
94	
95	        if (f != null) {
96	            TextView fileNameView = v.findViewById(R.id.fileTitle);
97	            TextView filePermissions = v.findViewById(R.id.filePermissions);
98	            TextView fileDate = v.findViewById(R.id.fileDate);
99	            TextView fileSize = v.findViewById(R.id.fileSize);
100	            ImageView fileImage = v.findViewById(R.id.fileIcon);
101	
102	            final String fileName = f.getName();
103	            if (fileNameView != null) {
104	                int maxLength = Integer.parseInt(new Pref<String>(FILENAME_LENGTH).getValue());
105	                if (fileName.length() >= maxLength) {
106	                    @SuppressLint("SetTextI18n") String output = fileName.substring(0, maxLength - 3) + "...";
107	                    fileNameView.setText(output); //shorten long names
108	                } else {
109	                    fileNameView.setText(fileName);
110	                }
111	            }
112	            if (filePermissions != null) {
113	                filePermissions.setText(f.getPermissions());
114	            }
115	            if (fileDate != null) {
116	                fileDate.setText(SimpleDateFormat.getDateTimeInstance().format(f.getLastModified()));
117	            }
118	            if (fileSize != null) {
119	                if (f.isDirectory()) {
120	                    fileSize.setVisibility(View.GONE);
121	                } else {
122	                    fileSize.setText(getSizeFormatted(f));
123	                }
124	            }
125	            if (fileImage != null) {
126	                if (!f.isDirectory()) {
127	                    if (f.isArchive()) {
128	                        fileImage.setImageDrawable(getContext().getDrawable(R.drawable.ic_perm_media_black_24dp));
129	                    } else {
130	                        fileImage.setImageDrawable(getContext().getDrawable(R.drawable.ic_insert_drive_file_black_24dp));
131	                    }
132	                }
133	            }
134	            if (f.isDirectory() || (f.isExplorableArchive() && new Pref<Boolean>(ZIPS_EXPLORABLE).getValue())) {
135	                v.setOnClickListener(v1 -> activity.loadPath(f.getFile().getAbsolutePath()));
136	            } else {
137	                v.setOnClickListener(v1 -> openFile(f));
138	            }
139	            v.setOnCreateContextMenuListener((menu, view, info) -> new ContextMenuUtil(activity, this).initializeContextMenu(f, fileName, menu));
140	
141	
142	            ImageButton contextButton = v.findViewById(R.id.contextMenuButton);
143	            contextButton.setOnClickListener(v1 -> {
144	                ((Vibrator) activity.getSystemService(Context.VIBRATOR_SERVICE)).vibrate(8);
145	                activity.getFileListView().showContextMenuForChild(v);
146	            });
147	
148	            CheckBox checkBox = v.findViewById(R.id.fileCheckBox);
149	            checkBox.setOnCheckedChangeListener((buttonView, isChecked) -> {
150	                if (isChecked && !isInContext(f)) {
151	                    activity.getFileOpContext().getSecond().add(f);
152	                } else if (!isChecked && isInContext(f)) {
153	                    removeFromContext(f);
154	                }
155	            });
156	
157	            if (new Pref<Boolean>(SHOW_MENU_BUTTON_INSTEAD_OF_CHECKBOX).getValue()) {
158	                checkBox.setVisibility(View.INVISIBLE);
159	                contextButton.setVisibility(View.VISIBLE);
160	            } else {
161	                checkBox.setVisibility(View.VISIBLE);
162	                contextButton.setVisibility(View.GONE);
163	            }
164	
165	            for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
166	                if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
167	                    v.setBackgroundColor(activity.getColorByAttr(R.attr.colorPrimary));
168	                    checkBox.setChecked(true);
169	                } else {
170	                    checkBox.setChecked(false);
171	                }
172	            }
173	        }
174	        return v;
175	    }
