177	    private boolean isInContext(FMFile f) {
178	        boolean res = false;
179	        for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
180	            if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
181	                res = true;
182	            }
183	        }
184	        return res;
185	    }
186	
187	    private void removeFromContext(FMFile f) {
188	        for (FMFile contextFile : activity.getFileOpContext().getSecond()) {
189	            if (contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
190	                activity.getFileOpContext().getSecond().remove(contextFile);
191	            }
192	        }
193	    }
194	}
