private boolean isInContext(FMFile f) {
    ArrayList<FMFile> contextFiles = activity.getFileOpContext().getSecond();
    //noinspection ForLoopReplaceableByForEach (index based loop avoids ConcurrentModificationException)
    for (int i = 0; i < contextFiles.size(); i++) {
        FMFile contextFile = contextFiles.get(i);
        if (contextFile != null && contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
            return true;
        }
    }
    return false;
}

private void removeFromContext(FMFile f) {
    ArrayList<FMFile> contextFiles = activity.getFileOpContext().getSecond();
    // Iterator#remove() is used here since removing from a list while iterating over it
    // using a for-each loop causes a ConcurrentModificationException.
    Iterator<FMFile> iterator = contextFiles.iterator();
    while (iterator.hasNext()) {
        FMFile contextFile = iterator.next();
        if (contextFile != null && contextFile.getFile().getAbsolutePath().equals(f.getFile().getAbsolutePath())) {
            iterator.remove();
        }
    }
